<template>
  <div class="cat-wrap">
    <canvas ref="cv" :width="W" :height="H" class="cat-canvas" />
    <span class="cat-label">LOADING...</span>
  </div>
</template>

<script setup>
import { onMounted, onUnmounted, ref } from 'vue'

const W = 112
const H = 112
const MS = 20

// 47 frames extracted from the original GIF, embedded as base64 PNG data
const FRAMES = ["", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""]

const cv = ref(null)
let timer = null
let imgs = []
let loaded = 0
let frame = 0

function startAnim () {
  const canvas = cv.value
  if (!canvas) return
  const ctx = canvas.getContext('2d')
  ctx.imageSmoothingEnabled = false
  function draw () {
    ctx.fillStyle = '#fff'      // ← 新增
    ctx.fillRect(0, 0, W, H)    // ← 新增
    ctx.clearRect(0, 0, W, H)   // ← 保留
    ctx.drawImage(imgs[frame], 0, 0, W, H)
    frame = (frame + 1) % imgs.length
  }
  draw()
  timer = setInterval(draw, MS)
}

onMounted(() => {
  imgs = FRAMES.map(b64 => {
    const img = new Image()
    img.src = 'data:image/png;base64,' + b64
    img.onload = () => { if (++loaded === FRAMES.length) startAnim() }
    return img
  })
})

onUnmounted(() => clearInterval(timer))
</script>

<style scoped>
.cat-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
}
.cat-canvas {
  image-rendering: pixelated;
  image-rendering: crisp-edges;
}
.cat-label {
  font-family: monospace;
  font-size: 12px;
  letter-spacing: 3px;
  color: #999;
  animation: blink 1s step-end infinite;
}
@keyframes blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.2; }
}
</style>
